INSERT INTO rehab_hmo_wording (row_id, unique_row, old_key, new_key, fields, en, note)
VALUES
  (29, true, '29|||מרפאות בריאות הנפש - פסיכיאטר ופסיכותרפיה', '29|||אבחון וטיפול במרפאה רב-מקצועית: טיפול פסיכיאטרי ופסיכותרפיה. במרפאה, וגם מקוון או בטלפון.', '{"org":"מכבי","svc":"אבחון וטיפול במרפאה רב-מקצועית: טיפול פסיכיאטרי ופסיכותרפיה. במרפאה, וגם מקוון או בטלפון.","meeting":"in_person","target":"מבוגרים, ילדים ונוער","region":"כל הארץ","cost":"קופת החולים. ביקור אצל פסיכיאטר בהשתתפות עצמית, ושאר השירותים ללא עלות.","specialty":"הפרעות אכילה, התמכרויות","approaches":"טיפול אישי, טיפול משפחתי, טיפול קבוצתי","notes":"אין צורך בהפניית רופא. הפונים ממלאים טופס, והמרפאה חוזרת תוך 5 ימי עבודה.","phone":"","phoneLabel":"","phoneShowNumber":false}'::jsonb, '{"org":"Maccabi","svc":"Assessment and treatment at a multidisciplinary clinic: psychiatric treatment and psychotherapy. At the clinic, and also online or by phone.","meeting":"in_person","target":"Adults, children, and youth","region":"Nationwide","cost":"The health fund. A visit to a psychiatrist has a copay, and the other services are at no cost.","specialty":"Eating disorders, addictions","approaches":"Individual therapy, family therapy, group therapy","notes":"No doctor referral is needed. People apply with a form, and the clinic replies within 5 business days.","phone":"","phoneLabel":""}'::jsonb, '25.11.2026: נבדק מול https://www.maccabi4u.co.il/eligibilites/2062/ מעודכן 5.3.25. *3555 ומספר החירום אינם בעמוד הזכאות. 34 ש״ח לא עולים לכרטיס. הניסוח אושר עם אצוות השיקום וקופות החולים.'),
  (66, true, '66|||ייעוץ והכוונה למשפחות בתחום בריאות הנפש · 18:00 - 22:00', '66|||ייעוץ והכוונה לבני משפחה של מתמודדי נפש. במרכז.', '{"org":"מרכז יה״ל","svc":"ייעוץ והכוונה לבני משפחה של מתמודדי נפש. במרכז.","meeting":"in_person","target":"בני משפחה, וגם אדם משמעותי אחר","region":"","cost":"","specialty":"","approaches":"","notes":"מופעל על ידי איכות בשיקום.","phone":"03-9559596","phoneLabel":"קו סיוע","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Yahel Center","svc":"Counseling and guidance for family members of people coping with mental illness. At the center.","meeting":"in_person","target":"Family members, and also another significant person","region":"","cost":"","notes":"Run by Eichut BeShikum.","phone":"03-9559596","phoneLabel":"Support line","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '25.11.2026: נבדק מול עמוד יה״ל באתר איכות בשיקום. השעות 18:00–22:00 אינן בעמוד. הניסוח אושר עם אצוות השיקום וקופות החולים.'),
  (67, true, '67|||סיוע למתמודדי נפש דרך שילובם בקהילה תוך ליווי מקצועי אישי', '67|||שיקום בקהילה למתמודדי נפש, עם ליווי אישי. בקהילה.', '{"org":"איכות בשיקום","svc":"שיקום בקהילה למתמודדי נפש, עם ליווי אישי. בקהילה.","meeting":"in_person","target":"מתמודדי נפש ובני משפחותיהם","region":"כל הארץ","cost":"","specialty":"","approaches":"","notes":"מרכזי יה״ל בכרטיס נפרד.","phone":"03-5552784","phoneLabel":"משרד","phoneShowNumber":false,"phone2":"03-9559596","phoneLabel2":"קו סיוע","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Eichut BeShikum","svc":"Community rehabilitation for people coping with mental illness, with personal accompaniment. In the community.","meeting":"in_person","target":"People coping with mental illness and their family members","region":"Nationwide","cost":"","notes":"The Yahel centers are on a separate card.","phone":"03-5552784","phoneLabel":"Office","phone2":"03-9559596","phoneLabel2":"Support line","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '25.11.2026: נבדק מול https://eychut.org.il/. הניסוח אושר עם אצוות השיקום וקופות החולים.'),
  (69, true, '69|||טיפול משפחתי-מערכתי למצבי משבר', '69|||הכשרה לדיאלוג פתוח. הארגון עצמו אינו נותן את הטיפול.', '{"org":"דיאלוג פתוח בישראל","svc":"הכשרה לדיאלוג פתוח. הארגון עצמו אינו נותן את הטיפול.","meeting":"","target":"","region":"כל הארץ","cost":"","specialty":"","approaches":"","notes":"הטיפול אצל בוגרים בשוק הפרטי, במרפאה בעכו ובכפר שאול, ובפרויקט מעגלים בחיפה, בנצרת ובחוף הכרמל.","phone":"04-9059215","phoneLabel":"מעגלים","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Open Dialogue Israel","svc":"Training in Open Dialogue. The organization itself does not provide the treatment.","meeting":"","target":"","region":"Nationwide","cost":"","notes":"Treatment is with graduates in private practice, at a clinic in Acre and at Kfar Shaul, and in the Maagalim project in Haifa, Nazareth, and Hof HaCarmel.","phone":"04-9059215","phoneLabel":"Maagalim","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '25.11.2026: נבדק מול https://opendialogue.co.il/therapy/. הארגון מכשיר ואינו נותן את הטיפול, והאימייל אינו לפניות לטיפול. הניסוח אושר עם אצוות השיקום וקופות החולים.'),
  (70, true, '70|||תמיכה נפשית וחברתית בניצולי השואה והדור השני ', '70|||פסיכותרפיה לניצולי שואה ולבני הדור השני. בסניף או בבית.', '{"org":"עמך","svc":"פסיכותרפיה לניצולי שואה ולבני הדור השני. בסניף או בבית.","meeting":"in_person","target":"ניצולי שואה ובני הדור השני","region":"כל הארץ","cost":"לפי זכאות","specialty":"","approaches":"טיפול פרטני, טיפול קבוצתי, טיפול זוגי","notes":"יש גם מועדונים חברתיים. לניצולים יש מימון של משרד האוצר וועידת התביעות. לדור השני הפעילות מתקציב העמותה, מדמי חבר ומסיוע מגרמניה. בחלק מהמרכזים יש גם פסיכיאטר.","phone":"","phoneLabel":"","phoneShowNumber":false}'::jsonb, '{"org":"Amcha","svc":"Psychotherapy for Holocaust survivors and the second generation. At a branch or at home.","meeting":"in_person","target":"Holocaust survivors and the second generation","region":"Nationwide","cost":"According to eligibility","approaches":"Individual therapy, group therapy, couples therapy","notes":"There are also social clubs. For survivors there is funding from the Ministry of Finance and the Claims Conference. For the second generation the activity is from the organization budget, membership fees, and assistance from Germany. Some centers also have a psychiatrist.","phone":"","phoneLabel":""}'::jsonb, '25.11.2026: נבדק מול דפי הניצולים והדור השני באתר https://www.amcha.org/. כרטיס הטראומה נשאר נפרד. הניסוח אושר עם אצוות השיקום וקופות החולים.'),
  (71, true, '71|||לשילוב מתמודדים והעצמה בבריאות הנפש', '71|||עמותה של מתמודדים: שילוב, העצמה וקידום זכויות.', '{"org":"עמותת לשמה","svc":"עמותה של מתמודדים: שילוב, העצמה וקידום זכויות.","meeting":"","target":"","region":"","cost":"","specialty":"","approaches":"","notes":"","phone":"","phoneLabel":"","phoneShowNumber":false}'::jsonb, '{"org":"Lishma","svc":"An organization of people with lived experience: integration, empowerment, and advancing rights.","meeting":"","target":"","region":"","cost":"","notes":"","phone":"","phoneLabel":""}'::jsonb, '25.11.2026: נבדק מול https://www.lishma.co.il/. 054-531-6787 אינו בדף הבית. הניסוח אושר עם אצוות השיקום וקופות החולים.'),
  (72, true, '72|||תמיכה בילדים ונוער המטופלים במרכזי בריאות הנפש', '72|||פעילויות ותמיכה לילדים ולנוער בזמן אשפוז, וגם לבני משפחותיהם. בבית החולים.', '{"org":"זה בנפשי","svc":"פעילויות ותמיכה לילדים ולנוער בזמן אשפוז, וגם לבני משפחותיהם. בבית החולים.","meeting":"in_person","target":"ילדים ונוער המאושפזים, ובני משפחותיהם","region":"","cost":"","specialty":"","approaches":"","notes":"החצב 10, תל מונד. דבורה הנביאה 128, תל אביב.","phone":"051-2301343","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"zebenafshi@gmail.com","emailLabel":"אימייל","emailShowAddress":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false}'::jsonb, '{"org":"Ze BeNafshi","svc":"Activities and support for children and youth during hospitalization, and also for their family members. At the hospital.","meeting":"in_person","target":"Children and youth who are hospitalized, and their family members","region":"","cost":"","notes":"10 HaHatzav St, Tel Mond. 128 Dvora HaNevia St, Tel Aviv.","phone":"051-2301343","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"zebenafshi@gmail.com","emailLabel":"Email","email2":"","emailLabel2":"","email3":"","emailLabel3":""}'::jsonb, '25.11.2026: נבדק מול https://www.zebenafshi.com/. הניסוח אושר עם אצוות השיקום וקופות החולים.'),
  (73, true, '73|||נתיבי שיקום והחלמה', '73|||ליווי טיפולי ושיקומי למצבי תקיעות ומשבר. במפגש.', '{"org":"מכון צוהר","svc":"ליווי טיפולי ושיקומי למצבי תקיעות ומשבר. במפגש.","meeting":"in_person","target":"","region":"כל הארץ","cost":"","specialty":"","approaches":"","notes":"לכל אזור יש גם כתובת אימייל באתר.","phone":"050-7297727","phoneLabel":"ניהול","phoneShowNumber":false,"phone2":"052-6797493","phoneLabel2":"צפון","phoneShowNumber2":false,"phone3":"050-3030560","phoneLabel3":"מרכז","phoneShowNumber3":false,"phone4":"054-5442964","phoneLabel4":"ירושלים","phoneShowNumber4":false,"phone5":"054-4212721","phoneLabel5":"שרון","phoneShowNumber5":false,"phone6":"054-6284266","phoneLabel6":"תל אביב","phoneShowNumber6":false,"email":"max.tzohar@gmail.com","emailLabel":"ניהול","emailShowAddress":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false}'::jsonb, '{"org":"Machon Tzohar","svc":"Therapeutic and rehabilitation accompaniment for situations of being stuck and of crisis. At a meeting.","meeting":"in_person","target":"","region":"Nationwide","cost":"","notes":"Each region also has an email address on the site.","phone":"050-7297727","phoneLabel":"Management","phone2":"052-6797493","phoneLabel2":"North","phone3":"050-3030560","phoneLabel3":"Center","phone4":"054-5442964","phoneLabel4":"Jerusalem","phone5":"054-4212721","phoneLabel5":"Sharon","phone6":"054-6284266","phoneLabel6":"Tel Aviv","email":"max.tzohar@gmail.com","emailLabel":"Management","email2":"","emailLabel2":"","email3":"","emailLabel3":""}'::jsonb, '25.11.2026: נבדק מול https://www.machon-tzohar.com/. הניסוח אושר עם אצוות השיקום וקופות החולים.'),
  (74, true, '74|||שיקום ובריאות הנפש', '74|||שיקום בקהילה למתמודדי נפש: דיור, חונכות, סומכות וליווי בלימודים. בקהילה.', '{"org":"חברת נתן","svc":"שיקום בקהילה למתמודדי נפש: דיור, חונכות, סומכות וליווי בלימודים. בקהילה.","meeting":"in_person","target":"","region":"כל הארץ","cost":"סל שיקום, אגף השיקום, או פרטי","specialty":"","approaches":"","notes":"","phone":"072-3926558","phoneLabel":"מוקד","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Nathan","svc":"Community rehabilitation for people coping with mental illness: housing, mentoring, supported companionship, and support with studies. In the community.","meeting":"in_person","target":"","region":"Nationwide","cost":"The rehabilitation basket, the rehabilitation division, or private","notes":"","phone":"072-3926558","phoneLabel":"Call center","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '25.11.2026: נבדק מול עמוד שיקום ובריאות הנפש באתר https://nathan.co.il/. רשימת הסניפים לא עולה לכרטיס. הניסוח אושר עם אצוות השיקום וקופות החולים.'),
  (80, false, '80|||מרפאות בריאות הנפש - פסיכיאטר ופסיכותרפיה', '80|||טיפול פסיכיאטרי ופסיכותרפיה. במרפאה, וגם בשיחת וידאו.', '{"org":"מאוחדת","svc":"טיפול פסיכיאטרי ופסיכותרפיה. במרפאה, וגם בשיחת וידאו.","meeting":"in_person","target":"לקוחות מאוחדת","region":"כל הארץ","cost":"קופת החולים","specialty":"","approaches":"","notes":"במרפאה של הקופה או במרפאה ציבורית, אחרי פגישת מיון. אצל מטפל עצמאי יש השתתפות עצמית, בלי פגישת מיון.","web":"https://www.meuhedet.co.il/%D7%9E%D7%90%D7%95%D7%97%D7%93%D7%AA-%D7%9C%D7%A0%D7%A4%D7%A9/%D7%90%D7%9C-%D7%AA%D7%94%D7%99%D7%95-%D7%9C%D7%91%D7%93/","phone":"*3833","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Meuhedet","svc":"Psychiatric treatment and psychotherapy. At the clinic, and also in a video call.","meeting":"in_person","target":"Meuhedet members","region":"Nationwide","cost":"The health fund","notes":"At a fund clinic or a public clinic, after an intake meeting. With an independent therapist there is a copay, with no intake meeting.","phone":"*3833","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '25.11.2026: נבדק מול עמוד אל תהיו לבד באתר מאוחדת. מספר החירום וההמלצה מרופא משפחה אינם בעמוד. תעריפי ההשתתפות לא עולים לכרטיס. הניסוח אושר עם אצוות השיקום וקופות החולים.'),
  (81, false, '81|||מרפאות בריאות הנפש - פסיכיאטר ופסיכותרפיה', '81|||טיפול פסיכיאטרי ופסיכותרפיה.', '{"org":"לאומית","svc":"טיפול פסיכיאטרי ופסיכותרפיה.","meeting":"","target":"לקוחות לאומית","region":"כל הארץ","cost":"קופת החולים","specialty":"","approaches":"","notes":"אפשר לפנות ישירות ב-*507, וגם דרך רופא. להמשך טיפול במכון או אצל ספק נדרשת התחייבות.","phone":"*507","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Leumit","svc":"Psychiatric treatment and psychotherapy.","meeting":"","target":"Leumit members","region":"Nationwide","cost":"The health fund","notes":"A person can apply directly at *507, and also through a doctor. Continued treatment at an institute or with a supplier needs a commitment form.","phone":"*507","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '25.11.2026: נבדק מול https://www.leumit.co.il/mental-health-arena/. 1-800-240-240 אינו בעמוד. הניסוח אושר עם אצוות השיקום וקופות החולים.'),
  (296, true, '296|||תעסוקה נתמכת, מועדון חברתי באשקלון, מכינת הד, דיור מוגן לבודדים / ליווי, וסייעים בחינוך', '296|||דיור בקהילה לצעירים אחרי משבר נפשי. בדירת שותפים.', '{"org":"עמותת גוונים","svc":"דיור בקהילה לצעירים אחרי משבר נפשי. בדירת שותפים.","meeting":"in_person","target":"צעירים 18–28, זכאי סל שיקום","region":"לוד, יוקנעם, עפולה, שדרות, טירת כרמל","cost":"סל שיקום","specialty":"","approaches":"","notes":"תוכנית הד, שנה עד 5 שנים. דרור היא תוכנית נפרדת לצעירים על הרצף האוטיסטי.","whatsapp":"","whatsappLabel":"","phone":"*9913","phoneLabel":"מוקד","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Gvanim","svc":"Community housing for young adults after a mental-health crisis. In a shared apartment.","meeting":"in_person","target":"Young adults ages 18-28 who are eligible for the rehabilitation basket","region":"Lod, Yokneam, Afula, Sderot, Tirat Carmel","cost":"The rehabilitation basket","notes":"The Had program, from one year to 5 years. Dror is a separate program for young adults on the autism spectrum.","whatsapp":"","whatsappLabel":"","phone":"*9913","phoneLabel":"Call center","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '25.11.2026: דף הבית לא נפתח. נבדק מול עמוד דיור בקהילה באתר גוונים. הוואטסאפ אינו בעמוד. הניסוח אושר עם אצוות השיקום וקופות החולים.'),
  (305, true, '305|||שיקום תעסוקתי, תעסוקה נתמכת, פנאי ומרכזי משפחות למתמודדי נפש מגיל 18', '305|||שיקום תעסוקתי, פנאי ומיצוי זכויות למתמודדי נפש ולבני משפחותיהם. בקהילה.', '{"org":"עזר מציון, האגף לבריאות הנפש","svc":"שיקום תעסוקתי, פנאי ומיצוי זכויות למתמודדי נפש ולבני משפחותיהם. בקהילה.","meeting":"in_person","target":"מתמודדי נפש מגיל 18 ובני משפחותיהם","region":"","cost":"","specialty":"","approaches":"","notes":"הרב רבינוב 5, בני ברק. קו ידידי נפש בכרטיס נפרד.","phone":"073-3952222","phoneLabel":"שיקום","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Ezra Mizion, the mental health department","svc":"Vocational rehabilitation, leisure, and help realizing rights for people coping with mental illness and their family members. In the community.","meeting":"in_person","target":"People coping with mental illness from age 18, and their family members","region":"","cost":"","notes":"5 HaRav Rabinow St, Bnei Brak. The Yedidei Nefesh line is on a separate card.","phone":"073-3952222","phoneLabel":"Rehabilitation","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '25.11.2026: נבדק מול https://www.ami.org.il/communities/mental-health. אזורי התעסוקה אינם בעמוד הזה. קו ידידי נפש נשאר כרטיס נפרד. הניסוח אושר עם אצוות השיקום וקופות החולים.'),
  (306, true, '306|||סל שיקום, דיור, תעסוקה וסיוע להורים מתמודדים', '306|||שיקום, טיפול ותמיכה. בבית או בקהילה.', '{"org":"שלו","svc":"שיקום, טיפול ותמיכה. בבית או בקהילה.","meeting":"in_person","target":"","region":"כל הארץ","cost":"","specialty":"","approaches":"","notes":"המלאכה 21, פארק אפק, ראש העין. בית משלך וציפור הנפש בכרטיסים נפרדים.","phone":"1599-504949","phoneLabel":"מוקד","phoneShowNumber":false,"phone2":"050-5962315","phoneLabel2":"נייד","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"info@slavpro.co.il","emailLabel":"אימייל","emailShowAddress":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false}'::jsonb, '{"org":"Slav","svc":"Rehabilitation, treatment, and support. At home or in the community.","meeting":"in_person","target":"","region":"Nationwide","cost":"","notes":"21 HaMelacha St, Afek Park, Rosh HaAyin. A Home of Your Own and Soulbird are on separate cards.","phone":"1599-504949","phoneLabel":"Call center","phone2":"050-5962315","phoneLabel2":"Mobile","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"info@slavpro.co.il","emailLabel":"Email","email2":"","emailLabel2":"","email3":"","emailLabel3":""}'::jsonb, '25.11.2026: נבדק מול https://slavpro.co.il/. העמוד מתאר את החברה כולה, ובית משלך וציפור הנפש נשארים כרטיסים נפרדים. הניסוח אושר עם אצוות השיקום וקופות החולים.'),
