  (777, true, '777|||תעסוקה נתמכת ופיתוח קריירה לזכאי סל שיקום', '777|||שיקום תעסוקתי ופיתוח קריירה לזכאי סל שיקום. בתוכנית, בעיר של המשתתף.', '{"org":"שיקום אחר","svc":"שיקום תעסוקתי ופיתוח קריירה לזכאי סל שיקום. בתוכנית, בעיר של המשתתף.","meeting":"in_person","target":"זכאי סל שיקום","region":"כל הארץ","cost":"סל שיקום","specialty":"","approaches":"","notes":"וורקאיט לגילאי 18–35. ג׳ובי היא תעסוקה נתמכת בשוק החופשי. אמצע החיים מגיל 45. המרץ 20, פתח תקווה.","founded":"2006","phone":"073-3745040","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"info@shikumacher.org.il","emailLabel":"אימייל","emailShowAddress":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false}'::jsonb, '{"org":"Shikum Acher","svc":"Vocational rehabilitation and career development for rehabilitation-basket recipients. In the program, in their city.","meeting":"in_person","target":"Rehabilitation-basket recipients","region":"Nationwide","founded":"2006","cost":"The rehabilitation basket","notes":"WorkIt is for ages 18-35. Joby is supported employment in the open market. Midlife is from age 45. 20 HaMeretz St, Petah Tikva.","phone":"073-3745040","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"info@shikumacher.org.il","emailLabel":"Email","email2":"","emailLabel2":"","email3":"","emailLabel3":""}'::jsonb, '25.11.2026: נבדק מול https://shikumacher.org.il/. הניסוח אושר עם אצוות השיקום וקופות החולים.');

UPDATE site_audit_entries s
SET card_keys = (
  SELECT COALESCE(array_agg(
    COALESCE((SELECT w.new_key FROM rehab_hmo_wording w WHERE w.old_key = k), k)
    ORDER BY ord
  ), '{}')
  FROM unnest(s.card_keys) WITH ORDINALITY AS u(k, ord)
)
WHERE EXISTS (
  SELECT 1
  FROM unnest(s.card_keys) k
  JOIN rehab_hmo_wording w ON w.old_key = k
);

UPDATE directory_card_edits c
SET card_key = w.new_key,
    public_fields = COALESCE(c.public_fields, '{}'::jsonb) || w.fields,
    translations = jsonb_set(
      COALESCE(c.translations, '{}'::jsonb),
      '{en}',
      COALESCE(c.translations->'en', '{}'::jsonb) || w.en,
      true
    ),
    eligibility = jsonb_set(
      COALESCE(c.eligibility, '{}'::jsonb),
      '{internal_notes}',
      to_jsonb(
        CASE
          WHEN COALESCE(c.eligibility->>'internal_notes', '') = '' THEN w.note
          ELSE rtrim(c.eligibility->>'internal_notes') || E'\n\n' || w.note
        END
      ),
      true
    ),
    public_edited_at = now(),
    updated_at = now()
FROM rehab_hmo_wording w
WHERE c.card_key = w.old_key
   OR (
     w.unique_row
     AND c.row_id = w.row_id
     AND (SELECT count(*) FROM directory_card_edits d WHERE d.row_id = w.row_id) = 1
   );

UPDATE directory_entries e
SET display_name = c.public_fields->>'org',
    description = c.public_fields->>'svc'
FROM directory_card_edits c
JOIN rehab_hmo_wording w ON w.new_key = c.card_key
WHERE e.entry_id = c.entry_id;

